// Native desktop pure workflow state machine: errors, cancellation and commits.
#include "inputworkflows.h"
#include <QApplication>
#include <QJsonArray>
#include <QDebug>
#include <cstdlib>
static int checks=0;
static void check(bool value,const char *message){++checks;if(!value){qCritical()<<"FAIL"<<message;std::exit(1);}}
int main(int argc,char **argv){
 QApplication app(argc,argv);
 InputWorkflows m;WorkflowRequest request;int commits=0,cancels=0; m.onEvaluate=[&](const WorkflowRequest&r){request=r;};m.onCommit=[&](const QString&,const QString&){++commits;};m.onCancel=[&](quint64){++cancels;};
 m.setMode(InputWorkflows::Mode::Rpn);m.setDraft("2");check(m.apply("enter")&&!request.commit,"RPN Enter validates without commit");check(m.stack().isEmpty(),"no premature push");m.complete(request.id,"2");m.setDraft("8");m.apply("enter");m.complete(request.id,"8");m.apply("-");check(request.expression=="(2)-(8)"&&request.commit,"RPN operand order");m.complete(request.id,"-6");check(m.stack()==QStringList{"-6"}&&commits==1,"RPN binary single commit");m.apply("enter");check(m.stack()==QStringList{"-6","-6"}&&commits==1,"empty Enter duplicates without commit");m.setDraft("0");m.apply("/");const auto before=m.stack();m.complete(request.id,{},"Division by zero");check(m.stack()==before&&m.draft()=="0"&&commits==1,"RPN error transaction rollback");m.setDraft("2");m.apply("+");auto stale=request.id;m.cancel();check(!m.complete(stale,"-4")&&m.stack()==before&&cancels==1,"cancelled reply cannot apply");m.setDraft("");m.apply("swap");m.apply("roll");m.apply("drop");check(m.stack().size()==1,"RPN stack operations");
 m.setMode(InputWorkflows::Mode::Classic);m.setDraft("2");m.apply("+");check(!request.commit,"Classic operator is preview");m.complete(request.id,"2");m.setDraft("3");m.apply("*");check(request.expression=="3"&&!request.commit,"Classic freezes right operand");m.complete(request.id,"3");check(request.expression=="(2)+(3)","Classic immediate chain expression");m.complete(request.id,"5");m.setDraft("4");m.apply("=");m.complete(request.id,"4");check(request.commit&&request.expression=="(5)*(4)","Classic equals expression");m.complete(request.id,"20");m.apply("=");check(request.expression=="(20)*(4)","Classic repeated equals");m.complete(request.id,"80");check(commits==3,"Classic equals commits once each");
 m.apply("clear");m.setDraft("50");m.apply("+");m.complete(request.id,"50");m.setDraft("20");m.apply("percent");check(request.expression=="(50)*((20)/100)"&&!request.commit,"Classic relative percent");m.complete(request.id,"10");m.apply("=");m.complete(request.id,"10");check(request.expression=="(50)+(10)","percent completes selected operation");m.complete(request.id,"60");m.setMode(InputWorkflows::Mode::Rpn);check(m.stack().size()==1,"mode switch preserves stack");
 m.setMode(InputWorkflows::Mode::Classic);m.apply("clear");m.setPercentMode(InputWorkflows::Percent::Direct);m.setDraft("50");m.apply("+");m.complete(request.id,"50");m.setDraft("20");m.apply("percent");check(request.expression=="(20)/100","Classic direct percent");m.complete(request.id,"1/5");m.apply("=");m.complete(request.id,"1/5");check(request.expression=="(50)+(1/5)","Direct percent equals preserves rational operand");m.complete(request.id,"251/5");m.setMode(InputWorkflows::Mode::Rpn);
 const auto saved=m.saveState();InputWorkflows restored;bool evaluated=false;restored.onEvaluate=[&](const WorkflowRequest&){evaluated=true;};check(restored.restoreState(saved)&&restored.stack()==m.stack()&&!evaluated,"parse-only workflow restoration");auto corrupt=saved;auto r=corrupt["rpn"].toObject();r["stack"]=QJsonArray{"1;save()"};corrupt["rpn"]=r;check(!restored.restoreState(corrupt)&&restored.stack()==m.stack(),"transactional malformed restoration");
 InputWorkflows matrices;matrices.setMode(InputWorkflows::Mode::Rpn);WorkflowRequest matrixRequest;matrices.onEvaluate=[&](const WorkflowRequest&r){matrixRequest=r;};matrices.setDraft("[1,2;3,4]");matrices.apply("enter");check(matrices.complete(matrixRequest.id,"[1, 2; 3, 4]")&&matrices.stack().size()==1,"RPN accepts canonical matrix row separators");
 const auto matrixState=matrices.saveState();InputWorkflows matrixRestored;check(matrixRestored.restoreState(matrixState)&&matrixRestored.stack()==matrices.stack(),"RPN canonical matrix state restores without evaluating");
 qInfo()<<"PASS"<<checks<<"desktop workflow state checks";return 0;
}
